#include <bits/stdc++.h>
using namespace std;

const int MOD = 998244353;
void sc(){
    int n;
    cin>>n;
    vector<int> a(n+1);
    vector<vector<int>> req_i(n+1);
    for(int i = 1;i <= n; i++){
        cin>> a[i];
        req_i[a[i]].push_back(i);
    }
    vector<long long> dp(1,1);
    for(int x =1; x <=n; x++){
        vector<long  long> next_dp(x + 1, 0);
        for(int l =0; l < x; l++){
            if(dp[l]==0) continue;
            int r = (x -1) -l;
            int pos_L = l+1;
            bool L_ok = true;
            for(int i : req_i[x]){
                int reqP= (i+1)/2;
                int prev_cntP = min(l,i) + max(0, (x - 1) - l - n + i);
                bool P_holds = (prev_cntP ==reqP - 1) && (pos_L <= i);
                int reqS = (n - i + 2) / 2;
                int prev_cntS = max(0, l - i + 1) + min((x - 1) - l, n -i + 1 );
                bool S_holds = (prev_cntS == reqS - 1) && (pos_L >= i);
                
                if(!P_holds && !S_holds){
                    L_ok = false;
                    break;
                }
            }
            
            if (L_ok){
                next_dp[l + 1] = (next_dp[l + 1] + dp[l]) % MOD;
            }
            
            if(x < n){
                int pos_R = n - r;
                bool R_ok = true;
                for( int i : req_i[x]){
                    int reqP = (i + 1) / 2;
                    int prev_cntP = min(l, i) +max(0, (x - 1) - l - n + i);
                    bool P_holds = (prev_cntP == reqP - 1 ) && (pos_R <= i);
                    
                    int reqS = (n - i + 2) / 2;
                    int prev_cntS = max(0, l - i + 1) + min(( x - 1) - l, n  - i + 1);
                    bool S_holds = (prev_cntS == reqS - 1) && (pos_R >= i);
                    
                    if( !P_holds && !S_holds){
                        R_ok = false;
                        break;
                    }
                }
                if(R_ok){
                    next_dp[l] = (next_dp[l]+ dp[l]) % MOD;
                }
            }
        }
        dp =next_dp;
    }
    
    long long ans = 0;
    for(int l = 0; l <= n; l++){
        ans = (ans+dp[l]) % MOD;
    }
    cout << ans << "\n";
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int umm;
    if(cin >> umm){
        while(umm--){
            sc();
        }
    }
    
    return 0;

}
